export const august21BlogBatch: NewPost[] = specs.map((spec, index) => {
  const fields = (spec ?? []) as unknown as string[];
  const slug = fields[0] ?? '';
  const title = fields[1] ?? '';
  const excerpt = fields[2] ?? '';
  const decision = fields[3] ?? '';
  const boundary = fields[4] ?? '';
  const risk = fields[5] ?? '';
  const handoff = fields[6] ?? '';
  const measure = fields[7] ?? '';
  const localBody = String(fields[8] ?? '');
  return ({
  slug, title, excerpt, minutes: 10 + (index % 3), publishedDate: '2026-08-21',
  image: `/blog-thumbnails/aug21-${slug.replace(/^philippines-/,'')}.png`,
  body: [...makeBody(title, decision, 'A source link and a brief evidence note', boundary, risk, handoff, measure), String(localBody ?? '')],
  });
});

export const august21PromptReceipts = specs.map((spec) => {
  const slug = String((spec as unknown as string[] | undefined)?.[0] ?? '');
  return { slug, prompt: `Distinct Gemini editorial hero for ${slug}; productivity-visual, Philippines-focused outsourced employment operations, no text, logos, watermark, or stock-photo look.` };
});
